<script setup lang="ts">
import type { ModelEntry, JsonValue, RuntimeGraphSummary } from '@zedflow/sdk'

const client=useClient()
import { HttpError } from '@zedflow/sdk'
import { httpDiagnostics } from '../../contextEngine'

import { useClient } from '@zedflow/vue'

import { computed, ref, shallowRef, watch } from 'vue'
import type { FlowFile, ModelSelection } from '@zedflow/sdk'

import { defaultContextValue } from '../../contextEngine'
import type { ContextFile } from '@zedflow/sdk'
import { exportedFlows, flowExports, runtimeModelNodes, preparedFlowHashes, type RuntimePreparation } from '../../compositionEngine'
import type { BridgeFile, PreparedRuntime, RuntimeSelection } from '@zedflow/sdk'
import AppDialog from '../AppDialog.vue'
import ModelBindingsPanel from '../ModelBindingsPanel.vue'
import ContextValueEditor from '../context/ContextValueEditor.vue'
import RuntimeGraphPreview from './RuntimeGraphPreview.vue'
const open=defineModel<boolean>('open',{required:true})
const props=defineProps<{workspaceId:string;flows:FlowFile[];models:ModelEntry[];flowKey?:string;selection?:RuntimePreparation|null}>()
const emit=defineEmits<{use:[preparation:RuntimePreparation];launch:[preparation:RuntimePreparation,input:JsonValue]}>()
const files=computed(()=>exportedFlows(props.flows)),bridges=shallowRef<BridgeFile[]>([])
const selectedFlow=ref(''),entry=ref(''),selectedBridges=ref<string[]>([]),preparation=shallowRef<RuntimePreparation>(),bindings=ref<Record<string,ModelSelection>>({}),input=shallowRef<JsonValue>('')
const contexts=ref<Record<string,{key:string;hash:string}>>({}),strategies=shallowRef<ContextFile[]>([])
const error=ref(''),pending=ref(false),showModels=ref(true)
let intent=0
const contract=computed(()=>flowExports(files.value.find(file=>file.key===selectedFlow.value)?.composition))
const signature=computed(()=>JSON.stringify([props.workspaceId,selectedFlow.value,entry.value,selectedBridges.value,contexts.value,props.flows.map(file=>[file.key,file.hash]),bridges.value.map(file=>[file.key,file.hash])]))
const preparedSignature=ref('')
const interactive=computed(()=>(preparation.value?.overview.interactive??preparation.value?.overview.instances[preparation.value.overview.entry.instance]?.interactive)!==false)
const stale=computed(()=>!!preparation.value&&signature.value!==preparedSignature.value)
async function load(){const id=props.workspaceId,request=++intent;pending.value=true;error.value='';try{const [value,catalogue]=await Promise.all([client.composition.listBridges({workspaceId:id}),client.context.list({workspaceId:id})]);if(request===intent){bridges.value=value;strategies.value=catalogue;selectedFlow.value=props.selection?.selection.flow||props.flowKey||files.value[0]?.key||'';entry.value=props.selection?.selection.entry||Object.keys(contract.value?.contract.entries||{})[0]||'';selectedBridges.value=[...(props.selection?.selection.bridges||[])];contexts.value={...(props.selection?.selection.contexts||{})};preparation.value=props.selection||undefined;bindings.value={...(props.selection?.bindings||{})};preparedSignature.value=props.selection?signature.value:''}}catch(cause){if(request===intent)error.value=String(cause instanceof Error?cause.message:cause)}finally{if(request===intent)pending.value=false}}
watch(open,value=>{if(value)void load();else intent++})
watch(selectedFlow,()=>{contexts.value={};entry.value=Object.keys(contract.value?.contract.entries||{})[0]||''},{flush:'sync'})
async function prepare(){const request=++intent,snapshot=signature.value,workspaceId=props.workspaceId;pending.value=true;error.value='';const selection:RuntimeSelection={contexts:JSON.parse(JSON.stringify(contexts.value)),flow:selectedFlow.value,entry:entry.value,bridges:[...selectedBridges.value],flowHashes:Object.fromEntries(props.flows.map(file=>[file.key,file.hash])),bridgeHashes:Object.fromEntries(bridges.value.map(file=>[file.key,file.hash]))};try{const result=await client.composition.prepare({workspaceId,selection});if(request!==intent||snapshot!==signature.value)return;const overview=result.overview,root=result.runtime.flows[overview.entry.instance],binding=root.exports.entries[entry.value];preparation.value={workspaceId,selection:{...selection,flowHashes:preparedFlowHashes(result.runtime.definitions),bridgeHashes:result.runtime.definitions.bridgeHashes},overview,models:runtimeModelNodes(overview),bindings:bindings.value,inputField:binding.inputField,inputType:root.exports.contract.entries[entry.value].input};preparedSignature.value=snapshot;input.value=defaultContextValue(preparation.value.inputType,overview.types);showModels.value=true}catch(cause){if(request===intent){error.value=String(cause instanceof Error?cause.message:cause);if(cause instanceof HttpError&&httpDiagnostics(cause).length)error.value=httpDiagnostics(cause).map(item=>`${item.path} : ${item.message}`).join('\n')}}finally{if(request===intent)pending.value=false}}
function selectContext(path:string,key:string){const file=strategies.value.find(file=>file.key===key);const next={...contexts.value};if(file?.strategy)next[path]={key:file.key,hash:file.hash};else delete next[path];contexts.value=next}
function use(launch=false){if(!preparation.value||stale.value)return;const value={...preparation.value,bindings:{...bindings.value}};if(launch)emit('launch',value,input.value);else emit('use',value);open.value=false}

</script>
<template><AppDialog v-model:open="open" title="Composer une exécution" wide><div class="runtime-prepare"><p class="ctx-hint">Choisissez un flow d’entrée et les bridges à activer. La préparation résout uniquement leurs dépendances et leurs contrats.</p><fieldset :disabled="pending"><div class="runtime-selection-fields"><label>Flow d’entrée<select aria-label="Flow d’entrée" v-model="selectedFlow"><option value="" disabled>Choisir un flow avec des contrats publics</option><option v-for="file in files" :key="file.key" :value="file.key">{{file.name}}</option></select></label><label>Entrée publique<select aria-label="Entrée publique" v-model="entry"><option v-for="name in Object.keys(contract?.contract.entries||{})" :key="name">{{name}}</option></select></label></div><h3>Bridges à activer</h3><label v-for="file in bridges" :key="file.key" class="check-field"><input v-model="selectedBridges" type="checkbox" :value="file.key" :disabled="!file.bridge"/>{{file.key}} <small>{{file.bridge?`${Object.keys(file.bridge.connections).length} connexions`:'Source invalide'}}</small></label><p v-if="!bridges.length" class="ctx-hint">Aucun bridge dans ce workspace. Vous pouvez préparer le flow seul.</p><button :disabled="!selectedFlow||!entry" @click="prepare">Préparer le graphe résolu</button></fieldset><p v-if="pending" role="status">Résolution des contrats…</p><p v-if="error" role="alert" class="ctx-error" style="white-space:pre-wrap">{{error}}</p><template v-if="preparation"><p v-if="stale" class="ctx-error">La sélection a changé. Préparez à nouveau le graphe avant de l’utiliser.</p><RuntimeGraphPreview :overview="preparation.overview"/><section v-if="preparation.models.length" aria-label="Contextes des inférences"><h3>Stratégie par inférence</h3><label v-for="node in preparation.models" :key="node.path">{{node.group}} · {{node.node.data.label}}<select :aria-label="`Stratégie de ${node.path}`" :value="contexts[node.path]?.key||''" :disabled="pending" @change="selectContext(node.path,($event.target as HTMLSelectElement).value)"><option value="">Définition du flow</option><option v-for="strategy in strategies" :key="strategy.key" :value="strategy.key" :disabled="!strategy.strategy">{{strategy.strategy?.name||strategy.key}} · {{strategy.hash.slice(0,10)}}</option></select></label><small>La stratégie sélectionnée utilise les liaisons de données de cette inférence. Préparez à nouveau le graphe pour vérifier ses contrats.</small></section><ModelBindingsPanel v-if="showModels&&preparation.models.length" :nodes="preparation.models" :models="models" :bindings="bindings" :busy="pending" @change="(path,selection)=>bindings[path]=selection" @close="showModels=false"/><ContextValueEditor v-if="preparation.inputType.kind!=='text'||!interactive" v-model="input" :type="preparation.inputType" :types="preparation.overview.types" label="Donnée d’entrée"/><footer><small>{{Object.keys(preparation.overview.instances).length}} instances · {{preparation.overview.bridges.length}} bridges activés</small><button v-if="preparation.inputType.kind==='text'&&interactive" class="primary" :disabled="pending||stale" @click="use()">Utiliser cette composition</button><button v-else class="primary" :disabled="pending||stale" @click="use(true)">Lancer avec cette donnée</button></footer></template></div></AppDialog></template>
<style scoped>.runtime-prepare{max-height:78vh;overflow:auto;padding:0 2px}.runtime-prepare fieldset{border:0;margin:0;padding:0}.runtime-selection-fields{display:flex;gap:14px;margin-bottom:18px}.runtime-selection-fields>label{flex:1;min-width:0}.runtime-prepare label{display:flex;flex-direction:column;gap:7px;font-size:12px;margin-bottom:10px}.runtime-prepare label.check-field{flex-direction:row;align-items:center}.runtime-prepare label.check-field input{width:auto}.runtime-prepare select,.runtime-prepare input,.runtime-prepare textarea{color:#dddde7;background:#25252b;border:1px solid #46464e;border-radius:5px;padding:7px;min-width:0}.runtime-prepare h3{font-size:13px;margin:18px 0 12px}.runtime-prepare>.runtime-graph-preview{margin-top:20px}.runtime-prepare small{font-size:11px;color:#9393a0}.runtime-prepare footer{margin:20px 0 5px}@media(max-width:650px){.runtime-selection-fields{flex-direction:column}.runtime-prepare{max-height:75vh}}</style>
